{"witnessCode": "import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('keepQueryParameters empty array regression', () => {
  it('should preserve query parameters when keepQueryParameters is []', () => {
    const input = 'https://example.com/path?foo=1&bar=2';
    const opts = { keepQueryParameters: [] };
    const expected = 'https://example.com/path?bar=2&foo=1';
    const actual = normalizeUrl(input, opts);
    assert.strictEqual(actual, expected);
  });
});"}
